public function stockReflect(int $id): Response
{
    if (!$InventoryPlan = $this->inventoryPlanRepository->find($id)) {
        throw $this->createNotFoundException();
    }

    if (!$InventoryPlan->isEditableBy($this->getMember())) {
        $this->addError('admin.inventory_plan_detail.not_editable_store', 'admin');

        return $this->redirectToRoute('admin_stock_inventory_plan_edit', ['id' => $InventoryPlan->getId()]);
    }

    // 在庫反映済みチェック
    if ($InventoryPlan->getStockReflectionedDate() !== null) {
        $this->addError('admin.inventory_plan.update.already_reflected', 'admin');

        return $this->redirectToRoute('admin_stock_inventory_plan_edit', ['id' => $InventoryPlan->getId()]);
    }

