// 差異未確認の詳細存在チェック
if ($this->inventoryPlanDetailRepository->checkUnconfirmedStockDifferenceDetailExists($InventoryPlan->getId())) {
    $this->addError('admin.inventory_plan.stock_reflect.unconfirmed_stock_difference', 'admin');

    return $this->redirectToRoute('admin_stock_inventory_plan_edit', ['id' => $InventoryPlan->getId()]);
}
